1	/**
2	 * check-jobs.ts — the one list `checks` is made of, and the two spellings it replaced.
3	 *
4	 * Every entry is a `domain/delivery/declared-jobs.ts` list entry. What an entry names
5	 * no longer chooses a LIST — there is one — it chooses a JOB, and the two jobs differ
6	 * in one thing: where the pull request is.
7	 *
8	 * An entry that names no secret runs in the pull request's tree, executing the change
9	 * in place, with no secret slot in the job at all. An entry that names one runs in the
10	 * default branch's tree and reads the pull request at `$ATOMATON_PR_TREE`, so a relative
11	 * path in its commands is a file a person released rather than one the change wrote.
12	 *
13	 * The rule underneath is a sentence: **the list and the commands are the default
14	 * branch's; a pull request's tree is data.** A pull request cannot add a check, rename
15	 * one, or widen the secrets one receives, because the list it could edit is not the
16	 * list that runs. That is what makes an entry naming `secrets` safe anywhere in it.
17	 *
18	 * `from_pull_request` and `from_default_branch` were the two arms this replaced. They
19	 * are still read, into this list, because the release that carries this reader reaches
20	 * a repository through an update that stops at a conflict for a person: until that
21	 * merge lands, `.github/atomaton/config.yaml` holds the old spelling and every pull
22	 * request's check has to stay green against it.
23	 */
24	import type { DeclaredJob, DeclaredJobsResolution, DeclaredJobsRules } from "./declared-jobs.ts";
25	import { resolveDeclaredJobs } from "./declared-jobs.ts";
26	import { CHECK_JOB_RESERVED } from "./declared-secrets.ts";
27	
28	/**
29	 * The list of checks.
30	 *
31	 * Read from the default branch, always — the planning job checks that branch out and
32	 * nothing reads a pull request's copy — so an entry may name its own `secrets`, and the
33	 * job that takes it runs in the default branch's tree.
34	 */
35	export const CHECKS: DeclaredJobsRules = { where: "checks.jobs", secrets: CHECK_JOB_RESERVED };
36	
37	/**
38	 * The two keys this list replaced, in the order they are read.
39	 *
40	 * Both are read under the same rules as `checks.jobs`, including the right to name a
41	 * credential: the reason `from_pull_request` refused one — its commands were the pull
42	 * request's own — is the reason the arm no longer exists.
43	 */
44	export const LEGACY_CHECK_KEYS = ["from_pull_request", "from_default_branch"] as const;
45	
46	export interface ChecksResolution extends DeclaredJobsResolution {
47	  /**
48	   * The keys an old config used, as `checks.from_pull_request` and friends.
49	   *
50	   * Returned rather than printed here: this module is a pure function of a config, and
51	   * the reader that talks to a person is what says so — once, however many entries the
52	   * old spelling held.
53	   */
54	  readonly deprecated: readonly string[];
55	}
56	
57	/**
58	 * Every check this configuration declares, from either spelling.
59	 *
60	 * One list out, because that is what runs: the two arms were two shapes of one answer,
61	 * and the workflow that consumes this has no use for the one they came from.
62	 */
63	export function resolveChecks(section: unknown): ChecksResolution {
64	  const container = typeof section === "object" && section !== null ? (section as Record<string, unknown>) : {};
65	  const problems: string[] = [];
66	  const jobs: DeclaredJob[] = [];
67	  const declaredIn = new Map<string, string>();
68	  const deprecated: string[] = [];
69	
70	  for (const key of ["jobs", ...LEGACY_CHECK_KEYS]) {
71	    const raw = container[key];
72	    if (raw === undefined) continue;
73	    const rules: DeclaredJobsRules = key === "jobs" ? CHECKS : { where: `checks.${key}`, secrets: CHECK_JOB_RESERVED };
74	    if (key !== "jobs") deprecated.push(rules.where);
75	
76	    const resolved = resolveDeclaredJobs(raw, rules);
77	    problems.push(...resolved.problems);
78	    // Across the keys as well as within one, because a name is a job name wherever it
79	    // sits: the config most likely to hold two of them is one halfway through the move,
80	    // with the entries under `jobs` and the old key not deleted yet.
81	    for (const job of resolved.jobs) {
82	      const already = declaredIn.get(job.name);
83	      if (already !== undefined) {
84	        problems.push(`\`${rules.where}\`: '${job.name}' is already declared in \`${already}\`.`);
85	        continue;
86	      }
87	      declaredIn.set(job.name, rules.where);
88	      jobs.push(job);
89	    }
90	  }
91	
92	  return { jobs, problems, deprecated };
93	}
94	
95	/**
96	 * Said once, by the reader, for a config still holding the old spelling.
97	 *
98	 * Names the new spelling rather than only the old one: the reader of this line is being
99	 * told what to write, and "the old key is deprecated" leaves them looking for the new
100	 * one. It also says the two spellings now behave alike, because the thing an author of
101	 * the old config most needs to know is that nothing about their checks changed.
102	 */
103	export function deprecatedCheckNotice(keys: readonly string[]): string {
104	  const named = keys.map((key) => `\`${key}\``).join(" and ");
105	  return (
106	    `${named} ${keys.length === 1 ? "is" : "are"} read into \`checks.jobs\`, the one list of checks. ` +
107	    "An entry from either spelling now runs the same way: the list comes from the default branch, and " +
108	    "each entry may name its own `secrets`. Move the entries under `checks.jobs` when convenient."
109	  );
110	}
111	
112	/**
113	 * Whether the notice has been said in this process.
114	 *
115	 * Per process because that is the scope a person reads: one planning job, or one
116	 * deliverable check, says it once rather than once per entry or once per call.
117	 */
118	let saidDeprecated = false;
119	
120	/** Say, once in a process, that the old spelling was read into the one list. */
121	export function announceDeprecatedChecks(keys: readonly string[], log: (line: string) => void = console.error): void {
122	  if (saidDeprecated || keys.length === 0) return;
123	  saidDeprecated = true;
124	  log(`::warning::${deprecatedCheckNotice(keys)}`);
125	}
126	
127	/**
128	 * Said when the list is empty, and only then.
129	 *
130	 * A project that declares nothing to verify a change with has a required check that
131	 * passes every pull request without looking at it, which is the shape this repository
132	 * keeps finding: cover that is not. A project that named `your_workflow` has its own
133	 * check and this one is not dispatched for it, so it is not surprising there.
134	 */
135	export const NO_CHECKS =
136	  "This check verified nothing: `checks.jobs` in .github/atomaton/config.yaml is empty, " +
137	  "so a pull request satisfying it has not been tested. Add the commands that check this project, " +
138	  "or point `checks.your_workflow` at a workflow of your own.";

