1	#!/usr/bin/env bun
2	/**
3	 * plan_checks.ts — `checks` as a matrix.
4	 *
5	 * A workflow cannot read a file to decide its own jobs, so the list is published as a
6	 * job output and consumed with `fromJSON`. Each entry becomes one GitHub job, which is
7	 * what lets a job carry its own runner and its own secrets.
8	 *
9	 * ## Which configuration this reads
10	 *
11	 * The DEFAULT BRANCH's, and that is the whole design. The job that runs this checks
12	 * that branch out, so a pull request cannot add a check, rename one, or widen the
13	 * secrets one receives. The pull request's tree is where a project's own commands run
14	 * afterwards; it is never what decides which commands those are.
15	 *
16	 * ## An empty list is an answer
17	 *
18	 * A project with no checks publishes `[]`, GitHub skips the matrix jobs, and the job
19	 * that aggregates the verdicts treats `skipped` as a pass. A malformed list is NOT the
20	 * same thing: it fails here, because a check that could not be planned must not read as
21	 * a check that found nothing to do.
22	 *
23	 * Usage:
24	 *   plan_checks.ts
25	 */
26	import { getChecks } from "../../adapters/runner/config.ts";
27	import { NO_CHECKS } from "../../domain/delivery/check-jobs.ts";
28	import { publishMatrix } from "./lib/publish-matrix.ts";
29	import { defineScript } from "./lib/script-ref.ts";
30	
31	export const ref = defineScript(import.meta.url);
32	
33	export function main(): void {
34	  const { jobs, problems } = getChecks();
35	  if (problems.length > 0) {
36	    for (const problem of problems) console.error(`::error::${problem}`);
37	    console.error("::error::`checks` could not be read, so none of its entries ran.");
38	    process.exit(1);
39	  }
40	
41	  publishMatrix(jobs, { what: "`checks` job", warnWhenEmpty: NO_CHECKS });
42	}
43	
44	if (import.meta.main) main();

