59	  readonly keys: readonly string[];
60	  /**
61	   * Turn an entry's own keys into fields, or return null to drop the entry.
62	   *
63	   * Push to `problems` rather than throwing, for the same reason everything else
64	   * here does: one pass should report everything wrong with a configuration.
65	   */
66	  readonly read: (entry: Record<string, unknown>, where: string, problems: string[]) => Extra | null;
67	}
68	
69	export interface DeclaredJobsRules<Extra extends object = Record<never, never>> {
70	  /** How to name this list in a message — `checks.jobs`, say. */
71	  readonly where: string;
72	  /**
73	   * The names this list's job environment already uses.
74	   *
75	   * Declaring one of them would replace a value the job depends on rather than add a
76	   * credential. The sets differ per list because the jobs do; `declared-secrets.ts`
77	   * owns each one.
78	   */
79	  readonly secrets: ReadonlySet<string>;
80	  /** Present only for a list with keys of its own. */
81	  readonly extra?: ExtraKeys<Extra>;
82	}
83	
84	export interface DeclaredJobsResolution<Extra extends object = Record<never, never>> {
85	  readonly jobs: readonly (DeclaredJob & Extra)[];
86	  readonly problems: readonly string[];
87	}
88	
89	/** Lowercase, hyphenated: it becomes a job name, and GitHub shows it as written. */
90	const NAME_PATTERN = /^[a-z0-9]+(-[a-z0-9]+)*$/;
91	
92	/** The keys every list understands. Anything else is a typo unless its owner allows it. */
93	const SHARED_KEYS = ["name", "runs_on", "commands", "secrets"] as const;
94	
95	function isRecord(value: unknown): value is Record<string, unknown> {
96	  return typeof value === "object" && value !== null && !Array.isArray(value);
97	}
98	
99	/**
100	 * Read a list of declared jobs.
101	 *
102	 * An absent list is an empty one and not a problem: declaring none is the shipped
103	 * default everywhere this is used.
104	 */
105	export function resolveDeclaredJobs<Extra extends object = Record<never, never>>(
106	  raw: unknown,
107	  rules: DeclaredJobsRules<Extra>,
108	): DeclaredJobsResolution<Extra> {
109	  if (raw === undefined || raw === null) return { jobs: [], problems: [] };
110	  if (!Array.isArray(raw)) return { jobs: [], problems: [`\`${rules.where}\` must be an array.`] };
111	
112	  const problems: string[] = [];
113	  const jobs: (DeclaredJob & Extra)[] = [];
114	  const seen = new Set<string>();
115	  const allowed = new Set<string>([...SHARED_KEYS, ...(rules.extra?.keys ?? [])]);
116	
117	  raw.forEach((entry, index) => {
118	    const where = `\`${rules.where}[${index}]\``;
119	    if (!isRecord(entry)) {
120	      problems.push(`${where} must be an object.`);
121	      return;
122	    }
123	
124	    // A misspelled key is silently nothing, and the job then runs without whatever it
125	    // was meant to carry -- a `secret:` that should have been `secrets:` is a job that
126	    // starts with no credential and fails somewhere further in.
127	    const unknown = Object.keys(entry).filter((key) => !allowed.has(key));
128	    if (unknown.length > 0) {
129	      problems.push(`${where}: unknown key(s) ${unknown.map((k) => `\`${k}\``).join(", ")}.`);
130	      return;
131	    }
132	
133	    const name = typeof entry.name === "string" ? entry.name.trim() : "";
134	    if (!NAME_PATTERN.test(name)) {
135	      problems.push(`${where}: \`name\` must be lowercase letters, digits and hyphens — e.g. 'cloud-names'.`);
136	      return;
137	    }
138	    if (seen.has(name)) {
139	      problems.push(`${where}: '${name}' is declared more than once.`);
140	      return;
141	    }
142	
143	    const commandsRaw = entry.commands ?? [];
144	    if (!Array.isArray(commandsRaw) || commandsRaw.some((c) => typeof c !== "string" || c.trim() === "")) {
145	      problems.push(`${where}: \`commands\` must be an array of non-empty shell commands.`);
146	      return;
147	    }
148	    const commands = (commandsRaw as string[]).map((c) => c.trim());
149	    // A job that runs nothing is a job that passes, and something that always passes
150	    // is the shape every guard here has failed in: it looks like cover and is not.
151	    if (commands.length === 0) {
152	      problems.push(`${where}: \`commands\` is empty, so this job would do nothing and report success.`);
153	      return;
154	    }
155	
156	    const secrets = readSecrets(entry.secrets, rules.secrets, `${rules.where}[${index}]`, where, problems);
157	    if (secrets === null) return;
158	
159	    const extra = rules.extra ? rules.extra.read(entry, where, problems) : ({} as Extra);
160	    if (extra === null) return;
161	
162	    const runner = resolveRunsOn(entry.runs_on);
163	    for (const problem of runner.problems) problems.push(`${where}: ${problem}`);
164	
165	    seen.add(name);
166	    jobs.push({ name, runsOn: runner.labels, commands, secrets, ...extra });
167	  });
168	
169	  return { jobs, problems };
170	}
