1	/**
2	 * publish-matrix.ts — hand a list of declared jobs to GitHub as a matrix.
3	 *
4	 * Both planning scripts end the same way, and the shape of what they publish is a
5	 * contract with the generated workflow rather than a detail of either: the matrix
6	 * `include` entries have to carry exactly the fields `actions/declared-job.ts` reads
7	 * back out of `matrix.*`. Two copies of that would agree until one of them gained a
8	 * field.
9	 */
10	import { appendFileSync } from "node:fs";
11	import type { DeclaredJob } from "../../../domain/delivery/declared-jobs.ts";
12	import { runsOnOutput } from "../../../domain/delivery/runner-label.ts";
13	
14	/**
15	 * A declared job, and optionally the tree it operates on.
16	 *
17	 * `ref` is a deployment's: a tag deployment selected by a merge still has to check
18	 * the TAG out, or the job ships the branch while reporting the tag's name. A check
19	 * has no such choice — it runs on the tree its arm already decided — so the field is
20	 * absent there rather than set to something meaningless.
21	 */
22	export type PublishableJob = { readonly job: DeclaredJob; readonly ref: string } | DeclaredJob;
23	
24	function partsOf(entry: PublishableJob): { job: DeclaredJob; ref: string } {
25	  return "job" in entry ? entry : { job: entry, ref: "" };
26	}
27	
28	export interface PublishMatrixOptions {
29	  /** What one entry is, for the line saying how many there were — "`deploy` job". */
30	  readonly what: string;
31	  /**
32	   * Said instead of the ordinary line when the list is empty, where empty is
33	   * surprising. Most lists are ordinarily empty and say nothing.
34	   */
35	  readonly warnWhenEmpty?: string;
36	}
37	
38	/** Write `jobs=<JSON>` to the step's output, and say on the log what was published. */
39	export function publishMatrix(jobs: readonly PublishableJob[], options: PublishMatrixOptions): void {
40	  // Each entry carries everything its job needs: the name GitHub shows, the machine,
41	  // the commands, and the secret names that job -- and only that job -- is handed.
42	  //
43	  // `runs_on` is JSON rather than a bare label so the consumer is always
44	  // `fromJSON(...)`, with no branch that behaves differently for one label than for
45	  // three. See `runsOnOutput`.
46	  const include = jobs.map(partsOf).map(({ job, ref }) => ({
47	    name: job.name,
48	    runs_on: runsOnOutput(job.runsOn),
49	    commands: job.commands,
50	    secrets: job.secrets,
51	    // Always present, empty where the job has no say: a matrix whose entries carried
52	    // different key sets would make `matrix.ref` undefined for some of them, and an
53	    // undefined `ref` on `actions/checkout` is not the same as an absent one.
54	    ref,
55	  }));
56	
57	  const output = process.env.GITHUB_OUTPUT;
58	  const line = `jobs=${JSON.stringify(include)}\n`;
59	  if (output) appendFileSync(output, line);
60	  else process.stdout.write(line);
61	
62	  if (include.length === 0) {
63	    console.error(
64	      options.warnWhenEmpty ? `::warning::${options.warnWhenEmpty}` : `No ${options.what}s to run.`,
65	    );
66	    return;
67	  }
68	  console.error(`${include.length} ${options.what}(s): ${include.map((job) => job.name).join(", ")}`);
